pub enum TimelineAuthoringCommand {
    /// Change the persisted Timeline duration.
    SetDocumentDuration {
        /// New inclusive final tick.
        duration: TimelineTick,
    },
    /// Change the presentation-only display frame rate.
    SetDisplayRate {
        /// New rational display rate.
        display_rate: TimelineDisplayRate,
    },
    /// Add a typed track.
    AddTrack(TimelineTrack),
    /// Remove a track.
    RemoveTrack(TimelineTrackId),
    /// Rename a track without changing stable identity.
    RenameTrack {
        /// Track.
        track: TimelineTrackId,
        /// New display name.
        name: String,
    },
    /// Change a track stable binding.
    SetBinding {
        /// Track.
        track: TimelineTrackId,
        /// Binding.
        binding: Option<TimelineBinding>,
    },
    /// Change persisted enabled state.
    SetTrackEnabled {
        /// Track.
        track: TimelineTrackId,
        /// Enabled.
        enabled: bool,
    },
    /// Change explicit runtime arbitration priority.
    SetTrackPriority {
        /// Track.
        track: TimelineTrackId,
        /// New priority.
        priority: i32,
    },
    /// Add a typed clip to a track.
    AddClip {
        /// Track.
        track: TimelineTrackId,
        /// Clip.
        clip: TimelineClip,
    },
    /// Delete a clip.
    RemoveClip(TimelineClipId),
    /// Duplicate one clip into its owning track with a caller-supplied stable ID.
    DuplicateClip {
        /// Existing source clip.
        clip: TimelineClipId,
        /// Stable identity for the duplicate.
        duplicate: TimelineClipId,
        /// Start tick for the duplicate.
        start: TimelineTick,
    },
    /// Rename a clip without changing stable identity.
    RenameClip {
        /// Clip.
        clip: TimelineClipId,
        /// New display name.
        name: String,
    },
    /// Move a clip without changing duration.
    MoveClip {
        /// Clip.
        clip: TimelineClipId,
        /// New start.
        start: TimelineTick,
    },
    /// Resize a clip.
    ResizeClip {
        /// Clip.
        clip: TimelineClipId,
        /// New duration.
        duration: TimelineTick,
    },
    /// Change a seekable clip source offset.
    SetClipSourceOffset {
        /// Clip.
        clip: TimelineClipId,
        /// New source offset.
        source_offset: TimelineTick,
    },
    /// Change adapter-consumed blend/fade durations.
    SetClipBlend {
        /// Clip.
        clip: TimelineClipId,
        /// New blend contract.
        blend: TimelineBlend,
    },
    /// Replace a clip's typed domain payload.
    SetClipPayload {
        /// Clip.
        clip: TimelineClipId,
        /// New typed payload.
        payload: TimelineClipPayload,
    },
    /// Insert or replace one Transform/Property curve key at its exact tick.
    SetPropertyKey {
        /// Transform/Property clip.
        clip: TimelineClipId,
        /// Typed key.
        key: TimelinePropertyKey,
    },
    /// Remove one Transform/Property curve key by exact tick.
    RemovePropertyKey {
        /// Transform/Property clip.
        clip: TimelineClipId,
        /// Clip-local key tick.
        tick: TimelineTick,
    },
    /// Add marker lane entry.
    AddMarker(TimelineMarker),
    /// Remove marker.
    RemoveMarker(TimelineMarkerId),
    /// Rename marker without changing stable identity.
    RenameMarker {
        /// Marker.
        marker: TimelineMarkerId,
        /// New display name.
        name: String,
    },
    /// Move marker.
    MoveMarker {
        /// Marker.
        marker: TimelineMarkerId,
        /// Tick.
        tick: TimelineTick,
    },
    /// Replace or clear a sequence-level marker event.
    SetMarkerEvent {
        /// Marker.
        marker: TimelineMarkerId,
        /// New optional bounded event name.
        event: Option<String>,
    },
}
